<script setup>import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {useAuthStore} from '../stores/auth';import {ElMessage} from 'element-plus';const auth=useAuthStore(),router=useRouter(),loading=ref(false);const form=reactive({username:'student',password:'123456'});async function submit(){loading.value=true;try{await auth.login(form);ElMessage.success('欢迎进入实验室管理系统');router.push('/dashboard')}finally{loading.value=false}}</script>
<template><div class="login"><section class="brand"><div class="brand-inner"><div class="mark"><OfficeBuilding/></div><h1>让实验室管理<br/>更清晰、更高效</h1><p>统一管理预约申请、设备台账和维修流程，帮助师生快速找到合适的实验资源。</p><div class="metrics"><div><b>3</b><span>类用户角色</span></div><div><b>2</b><span>条业务闭环</span></div><div><b>24h</b><span>在线服务</span></div></div></div><div class="orb one"></div><div class="orb two"></div></section><section class="login-side"><div class="login-box"><div class="mobile-logo"><OfficeBuilding/> LabSpace</div><span class="eyebrow">LAB MANAGEMENT</span><h2>欢迎回来</h2><p class="hint">登录后即可预约实验室或处理管理事务</p><el-form @keyup.enter="submit"><el-form-item><el-input v-model="form.username" size="large" placeholder="请输入用户名"><template #prefix><User/></template></el-input></el-form-item><el-form-item><el-input v-model="form.password" type="password" show-password size="large" placeholder="请输入密码"><template #prefix><Lock/></template></el-input></el-form-item><el-button type="primary" size="large" :loading="loading" class="submit" @click="submit">登录系统</el-button></el-form><div class="demo"><b>演示账号</b><span>学生 student / 管理员 labadmin / 系统 admin</span><span>密码均为 123456</span></div></div></section></div></template>
<style scoped>.login{min-height:100vh;display:grid;grid-template-columns:56% 44%;background:#fff}.brand{position:relative;overflow:hidden;display:flex;align-items:center;padding:9vw;background:linear-gradient(145deg,#0e6d7d,#168f94 58%,#2e9dac);color:#fff}.brand-inner{position:relative;z-index:2;max-width:570px}.mark{width:62px;height:62px;border-radius:18px;background:#ffffff24;display:grid;place-items:center;font-size:30px;border:1px solid #ffffff35}.brand h1{font-size:48px;line-height:1.25;margin:32px 0 20px;letter-spacing:1px}.brand p{font-size:17px;line-height:1.9;color:#d9f3f3}.metrics{display:flex;gap:55px;margin-top:58px}.metrics div{display:flex;flex-direction:column}.metrics b{font-size:28px}.metrics span{font-size:13px;color:#c7e8e9;margin-top:5px}.orb{position:absolute;border-radius:50%;border:1px solid #ffffff16}.one{width:430px;height:430px;right:-120px;top:-100px;box-shadow:0 0 0 70px #ffffff08,0 0 0 140px #ffffff05}.two{width:220px;height:220px;left:-80px;bottom:-80px;background:#ffffff08}.login-side{display:grid;place-items:center;padding:50px}.login-box{width:min(420px,100%)}.eyebrow{font-size:12px;color:var(--primary);font-weight:700;letter-spacing:2px}.login h2{font-size:34px;margin:12px 0 8px}.hint{color:var(--muted);margin-bottom:32px}.submit{width:100%;height:48px;font-size:16px}.demo{margin-top:28px;padding:16px 18px;background:var(--primary-light);border-radius:10px;display:flex;flex-direction:column;gap:6px;font-size:13px;color:#527177}.demo b{color:var(--primary-dark)}.mobile-logo{display:none}@media(max-width:850px){.login{grid-template-columns:1fr}.brand{display:none}.login-side{padding:30px}.mobile-logo{display:flex;align-items:center;gap:8px;color:var(--primary);font-weight:800;margin-bottom:50px}}</style>
